Web & Mobile Apps.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(web_mobile_apps, "Web & Mobile Apps") {
    Component(CrossPlatformUI, "Cross-Platform UI Layer", "Flutter/React", "Cross-platform UI providing resilient local-first client state and offline caching for rural areas.")
    Component(WebRTCModule, "WebRTC Video Module", "WebRTC", "Low-bandwidth video consultations supporting degraded connections below 300 kbit/s.")
    Component(StaticAssetDelivery, "Static Asset Delivery", "GCP Cloud CDN / Cloud Storage", "Global static asset delivery isolated across europe-west3 and us-central1.")
}

Rel(CrossPlatformUI, WebRTCModule, "Initiates video consultation streams")
Rel(CrossPlatformUI, StaticAssetDelivery, "Fetches static assets and cached resources")

@enduml

Consent & Audit Ledger.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Consent & Audit Ledger container

Container_Boundary(consent_and_audit_ledger, "Consent & Audit Ledger") {
    Component(Consent_Ledger_Manager, "Consent Ledger Manager", "Go", "Manages consent records and immutable audit logs with cryptographic integrity.")
    Component(Auditor_Reporting_API, "Auditor Reporting API", "Go / HTTPS", "Provides auditor reporting interface via HTTPS for compliance checks.")
    Component(PostgreSQL_Database_Engine, "PostgreSQL Database Engine", "Cloud SQL for PostgreSQL", "Regionally isolated data persistence secured via GCP Cloud KMS (CMEK), row-level security, and pgcrypto.")
}

Rel(Consent_Ledger_Manager, PostgreSQL_Database_Engine, "Persists audit logs and consent records", "PostgreSQL Wire Protocol")
Rel(Auditor_Reporting_API, Consent_Ledger_Manager, "Queries consent and audit data for compliance reporting")
@enduml

E-Prescription Dispatcher.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(e_prescription_dispatcher, "E-Prescription Dispatcher") {
    Component(Prescription_Receiver, "Prescription Receiver", "Go / gRPC", "Receives internal prescription dispatch requests from the Core Telehealth Service.")
    Component(Dispatch_Engine, "Dispatch Engine", "Go", "Orchestrates secure, reliable, and idempotent cross-border prescription routing.")
    Component(Pharmacy_Client, "Pharmacy Client", "Go / REST / HL7 FHIR", "Handles external communication and API interactions with regional pharmacies, health authorities, and payers.")
}

Rel(Prescription_Receiver, Dispatch_Engine, "Passes incoming dispatch requests")
Rel(Dispatch_Engine, Pharmacy_Client, "Triggers external prescription transmission")
@enduml
